<style>
/* Detail tambahan hero (adegan 1-3). Semua hiasan; dimatikan di mode ringan & reduced-motion. */
.hxn *{transform-box:fill-box}
.n-p1{translate:calc(var(--px,0)*-10px) calc(var(--py,0)*-6px);transition:translate .35s ease-out}
.n-p2{translate:calc(var(--px,0)*8px) calc(var(--py,0)*5px);transition:translate .35s ease-out}
.n-top{transform-origin:50% 0}.n-bot{transform-origin:50% 100%}.n-ctr{transform-origin:50% 50%}.n-lft{transform-origin:0 50%}
.hx-fx{position:absolute;inset:-4% -6%;pointer-events:none;z-index:0}
.hx-fx i{position:absolute;left:var(--x);bottom:2%;width:var(--s);height:var(--s);border-radius:50%;background:var(--gl,#dbe4ff);box-shadow:0 0 8px 2px var(--gl,#dbe4ff);opacity:0;animation:n-rise var(--t) linear var(--d) infinite}
.hx-fx i:nth-child(odd){--w:-18px}.hx-fx i:nth-child(even){--w:16px}
@keyframes n-rise{0%{opacity:0;transform:translate(0,0)}15%{opacity:.75}85%{opacity:.45}100%{opacity:0;transform:translate(var(--w,12px),-430px)}}

/* palet nomor soal di layar laptop */
.hx-screen{gap:.46rem}
.n-pal{display:flex;gap:3px}
.n-pal i{flex:1;height:14px;border-radius:3px;background:#e2e6ec;color:#667794;font:700 7px/14px sans-serif;text-align:center}
.n-pal i.d{background:#3b6cd4;color:#fff}.n-pal i.f{background:#f5c542;color:#1b2638}.n-pal i.c{background:#fff;color:#3b6cd4;box-shadow:inset 0 0 0 1.5px #3b6cd4}
.is-on .n-pal i.c{animation:n-cur 1.6s ease-in-out infinite}
.is-on .n-pal i.f{animation:n-flag 3s ease-in-out infinite}
.is-on .n-pal i.nx{animation:n-done 6s ease-in-out infinite;animation-delay:calc(var(--k)*.5s)}
@keyframes n-cur{50%{box-shadow:inset 0 0 0 1.5px #3b6cd4,0 0 0 3px rgb(59 108 212/.25)}}
@keyframes n-flag{50%{translate:0 -2px}}
@keyframes n-done{0%,30%{background:#e2e6ec;color:#667794}45%,90%{background:#3b6cd4;color:#fff}100%{background:#e2e6ec;color:#667794}}
.is-on .hx-screen::after{animation:n-glare 7s ease-in-out infinite}
@keyframes n-glare{0%,100%{translate:-30% 0;opacity:.18}50%{translate:30% 0;opacity:.42}}

.is-on .n-nd{animation:n-pulse 2.6s ease-in-out infinite}.is-on .n-nd:nth-child(2n){animation-delay:-.9s}.is-on .n-nd:nth-child(3n){animation-delay:-1.7s}
@keyframes n-pulse{50%{transform:scale(1.9);opacity:.45}}
.is-on .n-ln{animation:n-dash 2.2s linear infinite}
@keyframes n-dash{to{stroke-dashoffset:-16}}
.is-on .n-sway{animation:n-sway 4.2s ease-in-out infinite alternate}.is-on .n-sway.s{animation-duration:5.3s;animation-delay:-1.4s}
@keyframes n-sway{from{transform:rotate(-3.5deg)}to{transform:rotate(3.5deg)}}
.is-on .n-leaf{animation:n-leaf 3.6s ease-in-out infinite alternate}
@keyframes n-leaf{from{transform:rotate(-5deg)}to{transform:rotate(6deg)}}
.is-on .n-bub{animation:n-bub 8s ease-in-out infinite;animation-delay:calc(var(--k)*1s)}
@keyframes n-bub{0%,8%{transform:scale(0)}16%,84%{transform:scale(1)}94%,100%{transform:scale(0)}}
.is-on .n-tw{animation:n-tw 3.2s ease-in-out infinite;animation-delay:calc(var(--k,0)*-.7s)}
@keyframes n-tw{0%,100%{opacity:.1;transform:scale(.4)}50%{opacity:1;transform:scale(1)}}
.is-on .n-wifi{animation:n-wifi 2s ease-in-out infinite;animation-delay:calc(var(--k)*.25s)}
@keyframes n-wifi{0%,100%{opacity:.12}35%{opacity:1}}

/* adegan 2 */
.is-on .n-shoot{animation:n-shoot 7s ease-out infinite}
@keyframes n-shoot{0%,68%{opacity:0;translate:0 0}72%{opacity:1}88%,100%{opacity:0;translate:46px 30px}}
.is-on .n-cloud{animation:n-cloud 14s ease-in-out infinite alternate}
@keyframes n-cloud{from{translate:-34px 0}to{translate:44px 0}}
.is-on .n-curt{animation:n-curt 6s ease-in-out infinite alternate;transform-origin:50% 0}
