@keyframes n-dr{from{translate:0 6px;opacity:.15}to{translate:7px -12px;opacity:.85}}
.is-on .n-breath{animation:n-breath 4s ease-in-out infinite}
@keyframes n-breath{50%{transform:scaleY(1.09)}}
.is-on .n-tail{animation:n-tail 2.6s ease-in-out infinite alternate;transform-origin:100% 100%}
@keyframes n-tail{from{transform:rotate(-7deg)}to{transform:rotate(9deg)}}
.n-z{opacity:0}.is-on .n-z{animation:n-z 3.2s ease-out infinite}.n-z.z2{animation-delay:1.05s!important}.n-z.z3{animation-delay:2.1s!important}
@keyframes n-z{0%{opacity:0;translate:0 0;scale:.7}25%{opacity:1}100%{opacity:0;translate:12px -22px;scale:1.4}}
.is-on .n-eye{animation:n-blink 4.6s infinite}.is-on .n-eye.e2{animation-duration:5.4s;animation-delay:-2s}
@keyframes n-blink{0%,92%,100%{transform:scaleY(1)}95%{transform:scaleY(.08)}}

/* adegan 3 (siklus 10 detik, sama dengan alur pelamar dan HRD) */
.is-on .n-swing{animation:n-swing 3.6s ease-in-out infinite alternate;transform-box:view-box;transform-origin:154px 8px}
