.is-on .n-ring{animation:n-ring 10s ease-in-out infinite;transform-origin:50% 0}
@keyframes n-ring{0%,34%,50%,100%{transform:rotate(0)}37%{transform:rotate(16deg)}40%{transform:rotate(-14deg)}43%{transform:rotate(10deg)}46%{transform:rotate(-6deg)}}
.n-scan{opacity:0}.is-on .n-scan{animation:n-scan 10s linear infinite}
