        var copies = [].slice.call(root.querySelectorAll('[data-hx-copy]'));
        var ct = root.querySelector('[data-hx-ct]'), cd = root.querySelector('[data-hx-cd]'), auto = null;
        var reduce = matchMedia('(prefers-reduced-motion: reduce)').matches, cur = 0;

        function count(scope) {
            [].forEach.call(scope.querySelectorAll('[data-count]'), function (el) {
                var to = +el.dataset.count, sf = el.dataset.suffix || '', t0 = performance.now();
                if (reduce) { el.textContent = to + sf; return; }
                (function f(now) { var k = Math.min(1, (now - t0) / 1200); el.textContent = Math.round(to * (1 - Math.pow(1 - k, 3))) + sf; if (k < 1) requestAnimationFrame(f); })(t0);
            });
        }
        var segs = [].slice.call(root.querySelectorAll('[data-hx-seg]'));
        // Garis waktu: segmen aktif terisi 10 detik, selesai = lanjut ke adegan berikutnya (ikut jeda saat disentuh).
        function mark(n) {
            segs.forEach(function (s, i) {
                s.classList.remove('is-act', 'is-done'); void s.offsetWidth;
                if (i < n) s.classList.add('is-done'); else if (i === n) s.classList.add('is-act');
            });
        }
        function go(n) {
            n = (n + scenes.length) % scenes.length; cur = n; root.setAttribute('data-th', tabs[n].dataset.th);
            scenes.forEach(function (s, i) { s.classList.toggle('is-on', i === n); });
            copies.forEach(function (c, i) { c.classList.toggle('is-on', i === n); });
            ct.textContent = tabs[n].dataset.t; cd.textContent = tabs[n].dataset.d;
            [ct.parentNode].forEach(function (c) { c.classList.remove('swap'); void c.offsetWidth; c.classList.add('swap'); });
            count(scenes[n]); mark(n);
        }
        count(scenes[0]); mark(0);
        segs.forEach(function (s, i) {
            s.addEventListener('click', function () { go(i); });
            s.querySelector('b').addEventListener('animationend', function () { if (i === cur && !reduce) go(cur + 1); });
        });
        // Jam hitung mundur ujian (laptop). Sama persis dengan timer di server: tampilan ini hanya hiasan.
        var clocks = [].slice.call(root.querySelectorAll('[data-hx-clock]')), left = 14 * 60 + 32;
        function tick() { var m = Math.floor(left / 60), s = left % 60, v = (m < 10 ? '0' : '') + m + ':' + (s < 10 ? '0' : '') + s; clocks.forEach(function (c) { c.textContent = v; }); left = left > 0 ? left - 1 : 14 * 60 + 32; }
        if (!reduce) setInterval(function () { if (!document.hidden && !root.classList.contains('is-paused')) tick(); }, 1000);
        // Animasi tetap jalan saat kursor diarahkan ke panggung. Jeda hanya saat tab tersembunyi (lihat CSS .is-paused).
        document.addEventListener('visibilitychange', function () { root.classList.toggle('is-paused', document.hidden); });
        // Parallax kursor pada panggung.
        if (!reduce && matchMedia('(hover:hover)').matches) root.addEventListener('pointermove', function (e) {
            var r = root.getBoundingClientRect();
            root.style.setProperty('--px', ((e.clientX - r.left) / r.width - .5).toFixed(3));
            root.style.setProperty('--py', ((e.clientY - r.top) / r.height - .5).toFixed(3));
        });
    })();
</script>
